ALTER TABLE public.pm_payment_schedule_items ADD COLUMN invoice_description text;
ALTER TABLE public.pm_payment_schedule_items ADD COLUMN billing_plan_revision integer NOT NULL DEFAULT 0;
ALTER TABLE public.pm_payment_schedule_items ADD COLUMN manual_billing_group_id uuid;
CREATE TABLE public.pm_billing_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.pm_projects(id),description text NOT NULL,planned_date_override date,dissolved_at timestamptz,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pm_billing_groups TO authenticated;
GRANT ALL ON public.pm_billing_groups TO service_role;
REVOKE TRUNCATE ON public.pm_billing_groups FROM anon,authenticated;
ALTER TABLE public.pm_billing_groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_group_read ON public.pm_billing_groups FOR SELECT TO authenticated USING(public.is_psa_staff() AND public.can_view_project_area(project_id,'financials'));
ALTER TABLE public.pm_payment_schedule_items ADD CONSTRAINT pm_manual_billing_group_fk FOREIGN KEY(manual_billing_group_id) REFERENCES public.pm_billing_groups(id);
CREATE FUNCTION public.pm_billing_item_protected(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM pm_payment_schedule_items p WHERE p.id=_id AND (p.dates_frozen_at IS NOT NULL OR p.billing_status::text IN ('issued','paid','cancelled'))) OR EXISTS(SELECT 1 FROM financial_document_lines l JOIN financial_documents d ON d.id=l.document_id WHERE l.payment_schedule_item_id=_id AND d.status::text NOT IN ('draft','cancelled')); $$;
REVOKE ALL ON FUNCTION public.pm_billing_item_protected(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pm_billing_item_protected(uuid) TO service_role;
CREATE FUNCTION public.pm_billing_plan_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.invoice_description,NEW.manual_billing_group_id) IS DISTINCT FROM (OLD.invoice_description,OLD.manual_billing_group_id) THEN IF current_setting('pm.billing_action',true) IS DISTINCT FROM 'yes' OR public.pm_billing_item_protected(OLD.id) THEN RAISE EXCEPTION 'Use the guarded billing action; issued lines are locked' USING ERRCODE='42501'; END IF; END IF; IF (NEW.invoice_description,NEW.manual_billing_group_id,NEW.amount_value,NEW.vat_rate,NEW.planned_invoice_date_override,NEW.expected_invoice_date) IS DISTINCT FROM (OLD.invoice_description,OLD.manual_billing_group_id,OLD.amount_value,OLD.vat_rate,OLD.planned_invoice_date_override,OLD.expected_invoice_date) THEN NEW.billing_plan_revision:=OLD.billing_plan_revision+1; END IF; RETURN NEW; END $$;
CREATE TRIGGER pm_billing_plan_guard BEFORE UPDATE ON public.pm_payment_schedule_items FOR EACH ROW EXECUTE FUNCTION public.pm_billing_plan_guard();
CREATE FUNCTION public.pm_billing_plan(_project uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE rows jsonb;stages jsonb;BEGIN IF auth.uid() IS NULL OR NOT public.is_psa_staff() OR NOT public.can_view_project_area(_project,'financials') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; SELECT coalesce(jsonb_agg(public.pm_incoming_resolve(p.id)||jsonb_build_object('direction',p.direction,'description',coalesce(p.invoice_description,p.label),'revision',p.billing_plan_revision,'manual_group_id',p.manual_billing_group_id,'group_description',g.description,'group_date_override',g.planned_date_override,'supplier_name',coalesce(s.name,c.nome,p.supplier_label),'stage_completed',st.status::text='completed','protected',public.pm_billing_item_protected(p.id),'workflow',jsonb_build_object('confirmed_at',w.confirmed_at,'confirmed_by',w.confirmed_by,'note',w.note,'invoice_number',w.invoice_number,'issue_date',w.issue_date,'confirmation_current',w.confirmed_at IS NOT NULL AND w.confirmed_invoice_date IS NOT DISTINCT FROM (public.pm_incoming_resolve(p.id)->>'planned_invoice_date')::date AND w.confirmed_payment_date IS NOT DISTINCT FROM (public.pm_incoming_resolve(p.id)->>'planned_payment_date')::date AND w.confirmed_amount IS NOT DISTINCT FROM p.amount_value)) ORDER BY p.sort_order,p.id),'[]') INTO rows FROM pm_payment_schedule_items p LEFT JOIN pm_billing_groups g ON g.id=p.manual_billing_group_id AND g.dissolved_at IS NULL LEFT JOIN pm_suppliers s ON s.id=p.supplier_id LEFT JOIN companies c ON c.id=p.supplier_company_id LEFT JOIN pm_stages st ON st.id=p.stage_id LEFT JOIN pm_invoice_readiness w ON w.payment_item_id=p.id WHERE p.project_id=_project AND (p.direction='inflow' OR (p.direction='outflow' AND public.can_view_project_area(_project,'supplier_fees'))); SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'parent_stage_id',parent_stage_id,'sort_order',sort_order)),'[]') INTO stages FROM pm_stages WHERE project_id=_project; RETURN jsonb_build_object('rows',rows,'stages',stages,'today',(now() AT TIME ZONE 'Europe/Lisbon')::date,'can_edit',public.pm_can_edit_gantt(_project),'can_confirm',public.can_edit_project_payment_dates(_project),'can_issue',public.fin_invoice_queue_access() AND public.pm_payment_finance_access(_project),'can_read_suppliers',public.can_view_project_area(_project,'supplier_fees'));END $$;
REVOKE ALL ON FUNCTION public.pm_billing_plan(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_billing_plan(uuid) TO authenticated,service_role;
CREATE FUNCTION public.pm_billing_edit_description(_item uuid,_revision integer,_description text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p pm_payment_schedule_items;b jsonb;BEGIN SELECT * INTO p FROM pm_payment_schedule_items WHERE id=_item FOR UPDATE;IF p.id IS NULL OR NOT public.pm_can_edit_gantt(p.project_id) OR p.direction<>'inflow' OR public.pm_billing_item_protected(p.id) THEN RAISE EXCEPTION 'Forbidden or issued line' USING ERRCODE='42501';END IF;IF p.billing_plan_revision<>_revision THEN RAISE EXCEPTION 'Billing plan changed; reload' USING ERRCODE='40001';END IF;IF length(trim(coalesce(_description,''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Invoice description required';END IF;b:=to_jsonb(p);PERFORM set_config('pm.billing_action','yes',true);UPDATE pm_payment_schedule_items SET invoice_description=trim(_description) WHERE id=_item;UPDATE pm_invoice_readiness SET confirmed_at=NULL WHERE payment_item_id IN(SELECT id FROM pm_payment_schedule_items WHERE id=_item OR (p.manual_billing_group_id IS NOT NULL AND manual_billing_group_id=p.manual_billing_group_id));INSERT INTO pm_invoice_workflow_audit(project_id,payment_item_id,actor,action,before_values,after_values) VALUES(p.project_id,p.id,auth.uid(),'description',b,jsonb_build_object('description',trim(_description)));PERFORM set_config('pm.billing_action','',true);END $$;
REVOKE ALL ON FUNCTION public.pm_billing_edit_description(uuid,integer,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_billing_edit_description(uuid,integer,text) TO authenticated;
CREATE FUNCTION public.pm_billing_merge(_project uuid,_items uuid[],_revisions jsonb,_description text,_date date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p pm_payment_schedule_items;g uuid;n integer:=0;terms text;ent uuid;BEGIN IF NOT public.pm_can_edit_gantt(_project) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';END IF;IF cardinality(_items)<2 OR cardinality(_items)>100 OR cardinality(_items)<>(SELECT count(DISTINCT x) FROM unnest(_items) x) OR length(trim(coalesce(_description,''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Select two or more compatible planned invoices';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('billing-group:'||_project,0));FOR p IN SELECT * FROM pm_payment_schedule_items WHERE id=ANY(_items) ORDER BY id FOR UPDATE LOOP IF p.project_id<>_project OR p.direction<>'inflow' OR p.manual_billing_group_id IS NOT NULL OR public.pm_billing_item_protected(p.id) THEN RAISE EXCEPTION 'Select compatible unissued project invoices';END IF;IF (coalesce(_revisions->>p.id::text,'-1'))::integer<>p.billing_plan_revision THEN RAISE EXCEPTION 'Billing plan changed; reload' USING ERRCODE='40001';END IF;IF n=0 THEN terms:=p.payment_terms;ent:=p.entity_id;ELSIF p.payment_terms IS DISTINCT FROM terms OR p.entity_id IS DISTINCT FROM ent THEN RAISE EXCEPTION 'Incompatible invoice terms or entity';END IF;n:=n+1;END LOOP;IF n<>cardinality(_items) THEN RAISE EXCEPTION 'Missing invoice selection';END IF;INSERT INTO pm_billing_groups(project_id,description,planned_date_override) VALUES(_project,trim(_description),_date) RETURNING id INTO g;PERFORM set_config('pm.billing_action','yes',true);UPDATE pm_payment_schedule_items SET manual_billing_group_id=g WHERE id=ANY(_items);UPDATE pm_invoice_readiness SET confirmed_at=NULL WHERE payment_item_id=ANY(_items);INSERT INTO pm_invoice_workflow_audit(project_id,payment_item_id,actor,action,before_values,after_values) SELECT _project,id,auth.uid(),'merge',jsonb_build_object('group',NULL),jsonb_build_object('group',g,'description',trim(_description),'date',_date) FROM pm_payment_schedule_items WHERE id=ANY(_items);PERFORM set_config('pm.billing_action','',true);RETURN g;END $$;
REVOKE ALL ON FUNCTION public.pm_billing_merge(uuid,uuid[],jsonb,text,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_billing_merge(uuid,uuid[],jsonb,text,date) TO authenticated;
CREATE FUNCTION public.pm_billing_unmerge(_group uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g pm_billing_groups;p pm_payment_schedule_items;BEGIN SELECT * INTO g FROM pm_billing_groups WHERE id=_group AND dissolved_at IS NULL FOR UPDATE;IF g.id IS NULL OR NOT public.pm_can_edit_gantt(g.project_id) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';END IF;FOR p IN SELECT * FROM pm_payment_schedule_items WHERE manual_billing_group_id=g.id ORDER BY id FOR UPDATE LOOP IF public.pm_billing_item_protected(p.id) THEN RAISE EXCEPTION 'Issued groups cannot be undone';END IF;END LOOP;PERFORM set_config('pm.billing_action','yes',true);INSERT INTO pm_invoice_workflow_audit(project_id,payment_item_id,actor,action,before_values,after_values) SELECT g.project_id,id,auth.uid(),'unmerge',jsonb_build_object('group',g.id),jsonb_build_object('group',NULL) FROM pm_payment_schedule_items WHERE manual_billing_group_id=g.id;UPDATE pm_invoice_readiness SET confirmed_at=NULL WHERE payment_item_id IN(SELECT id FROM pm_payment_schedule_items WHERE manual_billing_group_id=g.id);UPDATE pm_payment_schedule_items SET manual_billing_group_id=NULL WHERE manual_billing_group_id=g.id;UPDATE pm_billing_groups SET dissolved_at=now() WHERE id=g.id;PERFORM set_config('pm.billing_action','',true);END $$;
REVOKE ALL ON FUNCTION public.pm_billing_unmerge(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_billing_unmerge(uuid) TO authenticated;
COMMENT ON TABLE public.pm_billing_groups IS 'Manual invoice presentation groups retain operational payment members; fiscal documents remain financial_documents.';